/* Bright, shadow-free projectile silhouettes retain original gameplay hitboxes. */
window.drawCombatProjectile=function(ctx,p,scale=1){if(p.life<=0)return;let angle=p.target?Math.atan2(p.target.y-p.y,p.target.x-p.x):Math.atan2(p.dy||0,p.dx||1),structure=['tower','nexus'].includes(p.source?.type),color=structure?'#ffc55b':p.color||'#c3f3ff',r=Math.max(structure?9:5,Math.min(17,(p.radius||3)*.8)),trail=p.waitRemaining>0?0:Math.max(25,Math.min(65,(p.speed||1200)*.035));if(p.pulse){ctx.strokeStyle=color;ctx.lineWidth=8;ctx.beginPath();ctx.arc(p.x,p.y,p.radiusNow,0,Math.PI*2);ctx.stroke();return}ctx.save();ctx.translate(p.x,p.y);if(p.yasuoTornado||p.yasuoQ&&p.third){let radius=p.radius||51.75,phase=(p.distance||0)/35;ctx.fillStyle='#a4e8ff25';ctx.strokeStyle='#72c9ed';ctx.lineWidth=3/scale;ctx.beginPath();ctx.moveTo(-radius*.25,8);ctx.quadraticCurveTo(-radius*.8,-70,-radius,-135);ctx.quadraticCurveTo(0,-160,radius,-135);ctx.quadraticCurveTo(radius*.7,-70,radius*.25,8);ctx.closePath();ctx.fill();ctx.stroke();for(let n=0;n<7;n++){ctx.strokeStyle=n%2?'#edfcff':'#9bddf5';ctx.lineWidth=(n%2?2.5:3.5)/scale;ctx.beginPath();ctx.ellipse(Math.sin(phase+n)*5,-n*21,radius*(.3+n*.115),4+n*1.4,Math.sin(phase+n)*.12,0,Math.PI*2);ctx.stroke()}ctx.strokeStyle='#bcecff88';ctx.lineWidth=2/scale;ctx.beginPath();ctx.ellipse(0,0,radius,radius*.3,0,0,Math.PI*2);ctx.stroke();ctx.restore();return}ctx.rotate(angle);ctx.lineCap='round';if(p.hovSpear||p.hovJudgement){ctx.strokeStyle='#20132f';ctx.lineWidth=7/scale;ctx.beginPath();ctx.moveTo(-48,0);ctx.lineTo(12,0);ctx.stroke();ctx.strokeStyle='#f7da8a';ctx.lineWidth=3/scale;ctx.stroke();ctx.fillStyle='#fff0b4';ctx.beginPath();ctx.moveTo(24,0);ctx.lineTo(4,-8);ctx.lineTo(9,0);ctx.lineTo(4,8);ctx.closePath();ctx.fill();if(p.hovStage>=2){ctx.strokeStyle='#b792eb';ctx.lineWidth=2/scale;ctx.beginPath();ctx.ellipse(-24,0,9,17,0,0,Math.PI*2);ctx.stroke()}ctx.restore();return}if(trail){ctx.strokeStyle='#071622dd';ctx.lineWidth=Math.max(5/scale,r*.9);ctx.beginPath();ctx.moveTo(-trail,0);ctx.lineTo(4,0);ctx.stroke();ctx.strokeStyle=color;ctx.lineWidth=Math.max(2.5/scale,r*.5);ctx.stroke()}ctx.fillStyle=color;ctx.strokeStyle='#092030';ctx.lineWidth=2/scale;ctx.beginPath();if(structure||p.source?.type==='monster'){ctx.arc(0,0,r,0,Math.PI*2)}else{ctx.moveTo(r*1.9,0);ctx.lineTo(-r,-r*.75);ctx.lineTo(-r*.3,0);ctx.lineTo(-r,r*.75);ctx.closePath()}ctx.fill();ctx.stroke();ctx.fillStyle='#fffbdc';ctx.beginPath();ctx.arc(r*.3,0,Math.max(2/scale,r*.33),0,Math.PI*2);ctx.fill();ctx.restore();if(p.code){ctx.font='bold '+(p.evolved?22:19)+'px monospace';ctx.textAlign='center';ctx.fillStyle=p.evolved?'#e3b7ff':'#b6ffec';ctx.fillText(p.evolved?'{</>}':'</>',p.x,p.y-15)}};
window.drawCombatImpact=function(ctx,u,time){let v=u.rangedImpactVisual;if(!v||time>=v.end)return;let p=Math.max(0,Math.min(1,(time-v.start)/(v.end-v.start)));ctx.save();ctx.translate(v.x,v.y);ctx.strokeStyle=v.color;ctx.globalAlpha=1-p;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,10+p*22,0,Math.PI*2);ctx.stroke();for(let i=0;i<4;i++){let a=i*Math.PI/2;ctx.beginPath();ctx.moveTo(Math.cos(a)*8,Math.sin(a)*8);ctx.lineTo(Math.cos(a)*(20+p*16),Math.sin(a)*(20+p*16));ctx.stroke()}ctx.restore()};
